		log.Fatal(err)
	}

	resultado, _, err := c.WebhookEndpointsAPI.CreateWebhookEndpoint(ctx).
		WebhookEndpointInput(entrada).
		Execute()
	if err != nil {
		log.Fatal(err)
	}
	fmt.Println(resultado)
}

